var ideas=[['今晚煮点热牛奶，配一首喜欢的歌，坐着喝完再收杯子。','剥一个橘子，把手机放远一点，慢慢吃。','把早餐装进喜欢的碗里，坐下来吃，别站着赶时间。'],['午后走到有阳光的地方，晒十分钟。风大就换到窗边。','回家时抬头看看天，拍下今天的颜色。','找一棵路边的树，隔几天看看它有什么变化。'],['问一句：“这周哪天有空，一起吃碗热汤面？”','给朋友发张今天遇到的小东西，说说为什么想起了对方。','和家人聊十分钟，问问他们今天吃了什么。'],['把床头收出放杯水的位置，今晚早点躺舒服。','换上干净的枕套，开一盏暖灯，读两页书。','把明早要穿的衣服放好，让起床少一点手忙脚乱。']];
function scene(i){var el=document.createElement('div');el.className='scene scene-'+i;el.setAttribute('aria-hidden','true');var shapes=['<div class="steam">﹏<br>﹏</div><div class="cup"></div>','<div class="sun"></div><div class="hill"></div><div class="snow s1">·</div><div class="snow s2">·</div>','<div class="letter">♡</div><div class="snow s1">·</div>','<div class="lamp"></div><div class="pool"></div><div class="book"></div>'];el.innerHTML=shapes[i];return el;}
var answers=[],pos=0,view=document.getElementById('view');
function button(text,fn,cls){var b=document.createElement('button');b.textContent=text;b.className=cls||'';b.addEventListener('click',fn);view.appendChild(b);}
function scrollPage(){window.scrollTo(0,0);}
function home(){view.innerHTML='<div class="meta">6 道题 / 约 1 分钟</div><h1>这个冬天，<br>做点什么会开心？</h1><p>回答六个小问题，挑几件合你心意的冬日小事。花点时间就能做，不必特意买东西。</p>';button('开始测一测 →',function(){answers=[];pos=0;question();},'primary');}
function question(){view.innerHTML='<div class="meta">'+(pos+1)+' / 6 · 按最近的感受选</div><div class="bar"><div style="width:'+((pos+1)/6*100)+'%"></div></div><h2>'+questions[pos][0]+'</h2>';questions[pos][1].forEach(function(t,i){button(String.fromCharCode(65+i)+'  '+t,function(){answers[pos]=i;pos++;if(pos===6){report();}else{question();}scrollPage();});});if(pos>0){button('← 返回上一题',function(){pos--;question();scrollPage();},'back');}}
function tally(a){var counts=[0,0,0,0];a.forEach(function(x){counts[x]++;});var max=Math.max.apply(null,counts);return {counts:counts,winners:counts.map(function(c,i){return c===max?i:-1;}).filter(function(i){return i>=0;})};}
function report(){var t=tally(answers);view.innerHTML='<div class="meta">你的冬日灵感卡</div><h1>'+(t.winners.length>1?'这几件事，都想试试':results[t.winners[0]][0])+'</h1><p>'+(t.winners.length>1?'你选这几种小事的次数一样多，今天想做哪件，就从哪件开始。':'照着你刚才的选择，给你挑了几件小事。')+'</p>';t.winners.forEach(function(i){var r=results[i];var card=document.createElement('section');card.className='card';card.appendChild(scene(i));var h=document.createElement('h2');h.textContent=r[0];card.appendChild(h);[r[1],r[2],r[3]].forEach(function(s){var p=document.createElement('p');p.textContent=s;card.appendChild(p);});var tip=document.createElement('p');tip.className='idea';var n=0;tip.textContent=ideas[i][n];card.appendChild(tip);var more=document.createElement('button');more.textContent='再换个点子';more.className='more';more.addEventListener('click',function(){n=(n+1)%ideas[i].length;tip.textContent=ideas[i][n];});card.appendChild(more);view.appendChild(card);});var d=document.createElement('details');var summary=document.createElement('summary');summary.textContent='结果是怎么算的？';d.appendChild(summary);var p=document.createElement('p');p.textContent='六题每个选择计一次。四类选择次数分别为：'+t.counts.join(' / ')+'（热饮、采光、联络、安放）。次数最多的一类作为结果，并列则全部展示。下次想法变了，也可以再来选。';d.appendChild(p);view.appendChild(d);button('修改最后一题',function(){pos=5;question();scrollPage();},'back');button('重新测一次',function(){home();scrollPage();},'primary');}
home();
document.addEventListener('visibilitychange',function(){document.body.classList.toggle('paused',document.hidden);});